{
  "name": "hitobito-tools",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "lint": "eslint"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "^0.123.0",
    "next": "16.2.6",
    "react": "19.2.6",
    "react-dom": "19.2.6"
  },
  "devDependencies": {
    "@types/node": "22.19.19",
    "@types/react": "19.2.14",
    "@types/react-dom": "19.2.3",
    "eslint": "9.39.4",
    "eslint-config-next": "16.2.6",
    "typescript": "5.9.3"
  }
}

import { NextRequest, NextResponse } from "next/server";

const TOOLS_HOST = "tools.hitobito.jp";
const DIGIL_CLOUD_HOST = "dc.hitobito.jp";
const LEVEL_UP_HOST = "levelup.hitobito.jp";
const FUTURE_FUNDING_HOST = "2100.hitobito.jp";
const LIFE_ONE_HOST = "life1.hitobito.jp";
const DROP_HOST = "drop.hitobito.jp";
const HABIT_PLANET_HOST = "habit-planet.hitobito.jp";
const HABIT_PLANET_ORIGIN = "https://habit-planet.hiratamanabu14.workers.dev";
const DROP_ROOT_PATH = "/drop";
const LEVEL_UP_ROOT_PATH = "/levelup";
const DIGIL_CLOUD_ROOT_PATH = "/ear-hub";

const FUTURE_IMAGE_REWRITES: Record<string, string> = {
  "/2100/monday-zero/monday-zero-hero.jpg": "/2100/monday-zero/hero.svg",
  "/2100/monday-zero/monday-zero-problem.jpg": "/2100/monday-zero/problem.svg",
};

export function proxy(request: NextRequest) {
  const host = (request.headers.get("host") ?? "").split(":")[0].toLowerCase();
  const { pathname } = request.nextUrl;

  if (host === HABIT_PLANET_HOST) {
    const target = new URL(`${pathname}${request.nextUrl.search}`, HABIT_PLANET_ORIGIN);
    return NextResponse.rewrite(target);
  }

  if (host === DIGIL_CLOUD_HOST) {
    if (
      pathname.startsWith("/_next") ||
      pathname.startsWith("/api") ||
      pathname === "/favicon.ico" ||
      pathname === "/favicon.svg"
    ) {
      return NextResponse.next();
    }

    // 旧URLは外向けの短いURLへ恒久リダイレクトする。
    if (pathname === DIGIL_CLOUD_ROOT_PATH) {
      const url = request.nextUrl.clone();
      url.pathname = "/";
      return NextResponse.redirect(url, 308);
    }

    if (pathname.startsWith(`${DIGIL_CLOUD_ROOT_PATH}/`)) {
      const url = request.nextUrl.clone();
      url.pathname = pathname.slice(DIGIL_CLOUD_ROOT_PATH.length) || "/";
      return NextResponse.redirect(url, 308);
    }

    // dc.hitobito.jp では /translate のような短いURLを見せつつ、
    // 実装は既存の /ear-hub/* をそのまま使う。
    const url = request.nextUrl.clone();
    url.pathname = pathname === "/" ? DIGIL_CLOUD_ROOT_PATH : `${DIGIL_CLOUD_ROOT_PATH}${pathname}`;
    return NextResponse.rewrite(url);
  }

  if (host === LEVEL_UP_HOST) {
    if (
      pathname.startsWith("/_next") ||
      pathname.startsWith("/api") ||
      pathname === "/favicon.ico" ||
      pathname === "/favicon.svg"
    ) {
      return NextResponse.next();
    }

    const url = request.nextUrl.clone();
    url.pathname = pathname === "/" ? LEVEL_UP_ROOT_PATH : `${LEVEL_UP_ROOT_PATH}${pathname}`;
    return NextResponse.rewrite(url);
  }

  if (host === TOOLS_HOST) {
    if (
      pathname.startsWith("/_next") ||
      pathname.startsWith("/api") ||
      pathname === "/favicon.ico" ||
      pathname === "/favicon.svg"
    ) {
      return NextResponse.next();
    }

    if (pathname === "/") {
      const url = request.nextUrl.clone();
      url.pathname = "/tools";
      return NextResponse.rewrite(url);
    }

    return NextResponse.next();
  }

  if (host === DROP_HOST) {
    if (
      pathname.startsWith("/_next") ||
      pathname.startsWith("/api") ||
      pathname === "/favicon.ico" ||
      pathname === "/favicon.svg"
    ) {
      return NextResponse.next();
    }

    if (pathname === "/") {
      const url = request.nextUrl.clone();
      url.pathname = DROP_ROOT_PATH;
      return NextResponse.rewrite(url);
    }

    return NextResponse.next();
  }

  if (host === LIFE_ONE_HOST) {
    const url = request.nextUrl.clone();

    if (pathname === "/robots.txt") {
      url.pathname = "/life1-robots.txt";
      return NextResponse.rewrite(url);
    }

    if (pathname === "/sitemap.xml") {
      url.pathname = "/life1-sitemap.xml";
      return NextResponse.rewrite(url);
    }

    if (
      pathname.startsWith("/_next") ||
      pathname.startsWith("/api") ||
      pathname === "/favicon.ico" ||
      pathname === "/favicon.svg"
    ) {
      return NextResponse.next();
    }

    if (pathname === "/") {
      url.pathname = "/life1";
      return NextResponse.rewrite(url);
    }

    if (pathname === "/app") {
      url.pathname = "/life-plus-one";
      return NextResponse.rewrite(url);
    }

    if (pathname === "/articles") {
      url.pathname = "/life1/articles";
      return NextResponse.rewrite(url);
    }

    if (pathname.startsWith("/articles/")) {
      url.pathname = `/life1${pathname}`;
      return NextResponse.rewrite(url);
    }

    if (pathname.startsWith("/diagnosis/")) {
      url.pathname = `/life1${pathname}`;
      return NextResponse.rewrite(url);
    }

    if (pathname === "/experiment") {
      url.pathname = "/life1/experiment";
      return NextResponse.rewrite(url);
    }

    return NextResponse.next();
  }

  if (host !== FUTURE_FUNDING_HOST) {
    return NextResponse.next();
  }

  const imageRewrite = FUTURE_IMAGE_REWRITES[pathname];
  if (imageRewrite) {
    const url = request.nextUrl.clone();
    url.pathname = imageRewrite;
    return NextResponse.rewrite(url);
  }

  if (
    pathname.startsWith("/_next") ||
    pathname.startsWith("/api") ||
    pathname === "/favicon.ico" ||
    pathname === "/favicon.svg"
  ) {
    return NextResponse.next();
  }

  if (pathname === "/") {
    const url = request.nextUrl.clone();
    url.pathname = "/2100";
    return NextResponse.rewrite(url);
  }

  return NextResponse.next();
}

export const config = {
  matcher: ["/((?!_next/static|_next/image).*)"],
};

{
  "compilerOptions": {
    "target": "ES2017",
    "lib": [
      "dom",
      "dom.iterable",
      "esnext"
    ],
    "allowJs": false,
    "skipLibCheck": true,
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "react-jsx",
    "incremental": true,
    "plugins": [
      {
        "name": "next"
      }
    ],
    "paths": {
      "@/*": [
        "./*"
      ]
    }
  },
  "include": [
    "next-env.d.ts",
    ".next/types/**/*.ts",
    "**/*.ts",
    "**/*.tsx",
    ".next/dev/types/**/*.ts"
  ],
  "exclude": [
    "node_modules"
  ]
}
